}

func (s *Service) startReviewRound(ctx *axi.Context, db *store.DB, home string, project store.Project, change store.Task, profile, name string) error {
	if project.IsDirectory() {
		return axi.Failure("review_round_unsupported", "directory Tasks cannot be reviewed as Git rounds", false)
	}
	if change.Type != "change" {
		return axi.Failure("review_round_target_invalid", "Review Rounds require a Change Task", false)
	}
	plan, err := change.AdmittedPlan()
	if err != nil {
		return admittedPlanFailure(err)
	}
	cfg, err := config.Load(home, project.Name)
	if err != nil {
		return err
	}
	sandbox, sandboxErr := db.SandboxByTask(ctx.Context, change.ID)
	if sandboxErr != nil && !store.IsNotFound(sandboxErr) {
		return sandboxErr
	}
	if sandboxErr != nil || sandbox.State != "held" || sandbox.TaskID != change.ID || filepath.Clean(sandbox.Path) != filepath.Clean(change.WorktreePath) {
		return axi.Failure("review_sandbox_missing", "Change Task does not hold its recorded Sandbox, so Review cannot use its checkout", false, "Relaunch the Change Task to reacquire its Sandbox, then retry `posse review start`")
	}
	if taskUsesGreenhouseReviewProvider(change, cfg, "") {
		var targets []store.ReviewTarget
		if project.IsWorkspace() {
			heads, err := greenhouseWorkspacePendingHeads(ctx.Context, db, project, change)
			if err != nil {
				return err
			}
			for _, member := range heads {
				targets = append(targets, store.ReviewTarget{Repository: member.Repository, Commit: member.Head})
			}
		} else {
			head, err := lockedTaskBranchAuthorHead(ctx.Context, project.Root, change.Branch)
			if err != nil {
				return err
			}
			targets = []store.ReviewTarget{{Repository: project.Name, Commit: head}}
		}
		if len(targets) > 0 {
			allPassed := true
			for _, target := range targets {
				passed, err := db.GreenhouseGatePass(ctx.Context, change.ID, target.Repository, target.Commit)
				if err != nil {
					return err
				}
				if !passed {
					allPassed = false
					break
				}
			}
			if allPassed {
				return ctx.Print(axi.Object{{Key: "task", Value: taskIDString(change.Seq)}, {Key: "review", Value: "Greenhouse Verdict reused"}})
			}
		}
		if err := s.startParallelGreenhouseReviews(ctx.Context, db, home, project, change, targets); err != nil {
			return err
		}
		return ctx.Print(axi.Object{{Key: "task", Value: taskIDString(change.Seq)}, {Key: "review", Value: "Greenhouse Verdict requested"}})
	}
	candidateReview := plan != nil && (plan.Review == "full-pipeline" || workspaceHasFullPipeline(plan))
	if candidateReview {
		pendingRefresh, err := db.OutstandingValidationFixHead(ctx.Context, change.ID, "freshness")
		if err != nil {
			return err
		}
		if pendingRefresh != "" {
			return ctx.Print(axi.Object{{Key: "task", Value: taskIDString(change.Seq)}, {Key: "state", Value: "refresh_queued"}, {Key: "help", Value: []any{"The target-refresh instruction is already in flight; wait for the Worker's next done Signal before starting Review"}}})
		}
		if change.State != store.StateWorking && change.State != store.StateStalled && change.State != store.StateDone && change.State != store.StateMerging {
			return axi.Failure("review_target_incomplete", "Change Task must be active before its private candidate can be reviewed", false, "Answer the Worker with `posse send "+taskIDString(change.Seq)+"`; a full-pipeline Worker requests Review with `posse signal done` after submitting its private candidates")
		}
		if err := s.prepareReviewCandidateCheckouts(ctx.Context, db, home, project, change, plan); err != nil {
			var failure *axi.Error
			if errors.As(err, &failure) && failure.Code == "candidate_target_moved" {
				return s.queueReviewTargetRefresh(ctx, db, project, change)
			}
			return err
		}
	} else if err := reviewableChange(change); err != nil {
		return err
	}
	plan, err = change.AdmittedPlan()
	if err != nil {
		return admittedPlanFailure(err)
	}
	if plan == nil || plan.ValidationLoops == nil || !plan.ValidationLoops.Review.Enabled {
		return axi.Failure("review_loop_disabled", "Change Task "+taskIDString(change.Seq)+" has no enabled, frozen Review Loop", false)
	}
	maxRounds := plan.ValidationLoops.MaxReviewRounds()
	if maxRounds < 1 || maxRounds > 3 {
		return axi.Failure("plan_invalid", "Change Task has an invalid frozen Review Round cap", false)
	}
	if plan.ValidationLoops.ReviewParallel == "greenhouse" {
		targets, err := changeCandidateTargets(ctx.Context, db, project, change)
		if err != nil {
			return err
		}
		if err := s.startParallelGreenhouseReviews(ctx.Context, db, home, project, change, targets); err != nil {
			return err
		}
	}
	if profile == "" {
		profile, err = s.autoStartReviewProfile(ctx.Context, project, home)
		if err != nil {
			return err
		}
	}
	generated, err := buildReviewRound(ctx.Context, db, project, change, *plan, maxRounds, home)
	if err != nil {
		return err
	}
	if name == "" {
		name = fmt.Sprintf("review-round-%d", generated.Admission.Round)
	}
	if err := validateWorkerName(name); err != nil {
		return invalidWorkerNameFailure(name, err)
	}
	args := []string{"--name", name}
	if profile != "" {
		args = append(args, "--profile", profile)
	}
	err = s.spawnTask(ctx, args, generated)
	var failure *axi.Error
	if errors.As(err, &failure) && failure.Code == "review_round_cap" {
		usage, usageErr := db.ReviewCapUsage(ctx.Context, change.ID)
		if usageErr != nil {
			return usageErr
		}
		used := reviewCapUsed(change, usage)
		binding, headErr := reviewCapHead(ctx.Context, db, project, change)
		if headErr != nil {
			return headErr
		}
		if noticeErr := s.raiseReviewCapNotice(ctx.Context, db, project, change, binding, used, maxRounds); noticeErr != nil {
			return noticeErr
		}
		return axi.Failure("review_round_cap", fmt.Sprintf("frozen Review and repair cap reached at %s (%d of %d rounds used)", binding.label(), used, maxRounds), false, "Wait for the User's `review_cap` Decision")
	}
	return err
}

func (s *Service) queueReviewTargetRefresh(ctx *axi.Context, db *store.DB, project store.Project, change store.Task) error {
	lanes, err := changedCandidateLanes(ctx.Context, db, project, change)
	if err != nil {
		return err
	}
	queued := false
	for _, lane := range lanes {
		candidate, err := db.LatestValidationCandidate(ctx.Context, change.ID, lane.repo)
		if err != nil {
			return err
		}
		targetHead, err := lane.targetHead(ctx.Context)
		if err != nil {
			return err
		}
		if candidate.State != store.ValidationCandidateStale && candidate.TargetSHA == targetHead {
			continue
		}
		if targetHead == "" {
			return axi.Failure("candidate_target_missing", lane.memberLabel("the frozen target branch is missing"), false)
		}
		freshness := prTargetFreshness{Branch: lane.targetBranch(), Tip: targetHead, Local: lane.localDelivery()}
		if err := queueTargetMergeInstruction(ctx.Context, db, change, lane.repo, freshness, candidate.CandidateSHA); err != nil {
			return err
		}
		queued = true
	}
	if !queued {
		return axi.Failure("candidate_target_moved", "candidate target changed before Review admission but no stale candidate lane remains", true)
	}
	if err := s.deliverNotices(ctx.Context, db, project); err != nil && !isHerdrUnavailable(err) {
		return err
	}
	return ctx.Print(axi.Object{{Key: "task", Value: taskIDString(change.Seq)}, {Key: "state", Value: "refresh_queued"}, {Key: "help", Value: []any{"Posse queued the target-refresh instruction; wait for the Worker's next done Signal before starting Review"}}})
}


